function hasCycle(graph) {
  const WHITE = 0, GRAY = 1, BLACK = 2;
  const color = {};
  for (const node in graph) color[node] = WHITE;
  const dfs = (node) => {
    color[node] = GRAY;
    for (const next of graph[node] || []) {
      if (color[next] === GRAY) return true;
      if (color[next] === WHITE && dfs(next)) return true;
    }
    color[node] = BLACK;
    return false;
  };
  for (const node in graph) {
    if (color[node] === WHITE && dfs(node)) return true;
  }
  return false;
}

const graph = { 0: [1], 1: [2], 2: [0], 3: [] };
console.log(hasCycle(graph));

