public class CycleDetection {
    boolean hasCycle(int[][] adj, int V) {
        boolean[] visited = new boolean[V];
        boolean[] recStack = new boolean[V];
        for (int i = 0; i < V; i++)
            if (!visited[i] && dfs(adj, i, visited, recStack)) return true;
        return false;
    }
    boolean dfs(int[][] adj, int v, boolean[] vis, boolean[] rec) {
        vis[v] = true; rec[v] = true;
        for (int u : adj[v]) {
            if (!vis[u] && dfs(adj, u, vis, rec)) return true;
            else if (rec[u]) return true; // back edge = cycle
        }
        rec[v] = false;
        return false;
    }
}

