def has_cycle(graph, n):
    WHITE, GRAY, BLACK = 0, 1, 2
    state = [WHITE] * n
    def dfs(u):
        state[u] = GRAY
        for v in graph.get(u, []):
            if state[v] == GRAY:
                return True
            if state[v] == WHITE and dfs(v):
                return True
        state[u] = BLACK
        return False
    return any(state[u] == WHITE and dfs(u) for u in range(n))

print(has_cycle({0: [1], 1: [2], 2: [0]}, 3))
